-- Idempotent install for config.retention_policy
-- Auto-generated from dbanalytics_install.backup. Safe to re-run (psql -f).

CREATE SCHEMA IF NOT EXISTS config;

CREATE SEQUENCE IF NOT EXISTS config.retention_policy_row_id_seq
    AS integer
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

CREATE TABLE IF NOT EXISTS config.retention_policy (
    row_id integer NOT NULL,
    server character varying(100) NOT NULL,
    table_name character varying(100) NOT NULL,
    days_to_keep integer DEFAULT '-1'::integer NOT NULL,
    entry_date timestamp without time zone DEFAULT now() NOT NULL
);

ALTER TABLE config.retention_policy ALTER COLUMN row_id SET DEFAULT nextval('config.retention_policy_row_id_seq'::regclass);
ALTER SEQUENCE config.retention_policy_row_id_seq OWNED BY config.retention_policy.row_id;

-- data: load only into a freshly-created (empty) table
DROP TABLE IF EXISTS _stg_load;
CREATE TEMP TABLE _stg_load (LIKE config.retention_policy);
SELECT row_id, server, table_name, days_to_keep, entry_date FROM _stg_load
WHERE NOT EXISTS (SELECT 1 FROM config.retention_policy);
DROP TABLE _stg_load;

SELECT setval('config.retention_policy_row_id_seq', GREATEST((SELECT COALESCE(max(row_id),0) FROM config.retention_policy),1), (SELECT count(*) FROM config.retention_policy) > 0);

DO $do$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint con
        JOIN pg_class c ON c.oid = con.conrelid
        JOIN pg_namespace n ON n.oid = c.relnamespace
        WHERE n.nspname = 'config' AND c.relname = 'retention_policy'
          AND con.conname = 'pk_retention_policy') THEN
        ALTER TABLE ONLY config.retention_policy
    ADD CONSTRAINT pk_retention_policy PRIMARY KEY (server, table_name);
    END IF;
END $do$;
